#!/usr/bin/env python3"""Скрипт для создания тестового пользователя"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from core.database import enginefrom models.user import Userfrom sqlmodel import Session, selectfrom core.auth import get_password_hashdef create_test_user():    """Создает тестового пользователя"""    with Session(engine) as session:        # Проверяем, есть ли уже пользователь        existing_user = session.exec(select(User).where(User.username == "test")).first()        if existing_user:            print(f"Пользователь 'test' уже существует (ID: {existing_user.id})")            return existing_user                # Создаем нового пользователя        user = User(            username="test",            email="test@example.com",            hashed_password=get_password_hash("test123"),            is_active=True        )                session.add(user)        session.commit()        session.refresh(user)                print(f"Создан пользователь: {user.username} (ID: {user.id})")        return userif __name__ == "__main__":    create_test_user()